180     };
181   }
182 
183   // ============================================================
184   // 应用层状态（内存变量；不使用任何持久化存储）
185   // ============================================================
186   let state = null;            // 当前局面
187   let highScore = 0;           // 会话内最高分（刷新页面即重置）
188   let timerId = null;          // 主循环定时器
189   let lastTickAt = 0;          // 上次推进时间戳（页面隐藏恢复后只推进单步）
