203   function drawGrid(context) {
204     context.fillStyle = '#0f172a';
205     context.fillRect(0, 0, CANVAS_SIZE, CANVAS_SIZE);
206 
207     context.strokeStyle = 'rgba(148, 163, 184, 0.16)';
208     context.lineWidth = 1;
209     for (let i = 1; i < GRID; i += 1) {
210       const pos = i * CELL;
211       context.beginPath();
212       context.moveTo(pos + 0.5, 0);
213       context.lineTo(pos + 0.5, CANVAS_SIZE);
214       context.stroke();
215       context.beginPath();
216       context.moveTo(0, pos + 0.5);
217       context.lineTo(CANVAS_SIZE, pos + 0.5);
218       context.stroke();
219     }
220 
221     context.strokeStyle = 'rgba(148, 163, 184, 0.5)';
222     context.strokeRect(0.5, 0.5, CANVAS_SIZE - 1, CANVAS_SIZE - 1);
223   }
224 
225   function drawSnake(context, snake) {
226     for (let i = 0; i < snake.length; i += 1) {
227       const cell = snake[i];
228       const pad = i === 0 ? 1 : 2;
229       context.fillStyle = i === 0 ? '#86efac' : '#22c55e';
230       context.fillRect(
231         cell.x * CELL + pad,
232         cell.y * CELL + pad,
233         CELL - pad * 2,
234         CELL - pad * 2
235       );
236     }
237   }
238 
239   function drawFood(context, food) {
240     if (!food) return;
241     const centerX = food.x * CELL + CELL / 2;
242     const centerY = food.y * CELL + CELL / 2;
243     context.fillStyle = '#f97316';
244     context.beginPath();
245     context.arc(centerX, centerY, CELL * 0.32, 0, Math.PI * 2);
246     context.fill();
247   }
248 
249   function drawOverLayer(context) {
250     context.fillStyle = 'rgba(2, 6, 23, 0.55)';
251     context.fillRect(0, 0, CANVAS_SIZE, CANVAS_SIZE);
252   }
253 
254   function render() {
255     if (!ctx || !state) return;
256     drawGrid(ctx);
257     drawFood(ctx, state.food);
258     drawSnake(ctx, state.snake);
259     if (state.status === STATUS_OVER) drawOverLayer(ctx);
260   }
261 
262   function setText(element, value) {
263     if (element && element.textContent !== value) {
264       element.textContent = value;
265     }
266   }
