268   function showOverlay() {
269     if (!dom || !dom.overlay) return;
270     dom.overlay.classList.remove('hidden');
271     dom.overlay.hidden = false;
272   }
273 
274   function hideOverlay() {
275     if (!dom || !dom.overlay) return;
276     dom.overlay.classList.add('hidden');
277     dom.overlay.hidden = true;
278   }
