280   /** HUD 同步：分数 / 会话最高分 / 结束页分数 / 结束层显隐 / 操作提示。 */
281   function syncHud() {
282     if (!dom || !state) return;
283     const isOver = state.status === STATUS_OVER;
284     setText(dom.score, String(state.score));
285     setText(dom.highScore, String(highScore));
286     setText(dom.finalScore, String(state.score));
