291     );
292     if (isOver) showOverlay();
293     else hideOverlay();
294   }
295 
296   // ============================================================
297   // 应用层：主循环、推进、最高分、重开
298   // ============================================================
299   function stopLoop() {
300     if (timerId !== null) {
301       clearInterval(timerId);
302       timerId = null;
303     }
304   }
305 
306   function startLoop() {
307     stopLoop();
308     lastTickAt = 0;
309     timerId = setInterval(tick, TICK_MS);
310   }
311 
312   function tick() {
313     if (!state || state.status !== STATUS_RUNNING) {
314       stopLoop();
315       return;
316     }
317     // 页面隐藏时浏览器会节流定时器：恢复后只推进单步，不做多步追赶
318     const current = now();
319     if (lastTickAt !== 0 && current - lastTickAt < TICK_MS * 0.5) return;
