    if (eventsBound || !dom) return;
    if (dom.document && typeof dom.document.addEventListener === 'function') {
      dom.document.addEventListener('keydown', onKeyDown);
      dom.document.addEventListener('visibilitychange', onVisibilityChange);
    }
