  // 公开接口：init / getState / reset（架构契约 4.2）
  // ============================================================
  function resolveDom(documentRef) {
    const doc = documentRef || (typeof document !== 'undefined' ? document : null);
    if (!doc || typeof doc.getElementById !== 'function') return null;
